const clean = (v) => String(v ?? '').replace(/<[^>]*>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#39;|&rsquo;|&lsquo;/g, "'").replace(/\s+/g, ' ').trim();
const clip = (v, max) => {
  const s = clean(v);
  if (s.length <= max) return s;
  const cut = s.slice(0, max - 1);
  const space = cut.lastIndexOf(' ');
  return (space > max * 0.6 ? cut.slice(0, space) : cut).replace(/[\s,.;:-]+$/, '') + '…';
};
const keyFrom = (...parts) => parts.join('-').replace(/[^a-z0-9]+/gi, '-').slice(-180);
const LIMITS = { tiktok: 2200, instagram: 2200, youtube: 4900, facebook: 2200, linkedin: 2900, twitter: 280, threads: 500, bluesky: 300, snapchat: 160 };
const NAMES = { tiktok: 'TikTok', instagram: 'Instagram', youtube: 'YouTube', facebook: 'Facebook', linkedin: 'LinkedIn', twitter: 'X', threads: 'Threads', bluesky: 'Bluesky', snapchat: 'Snapchat' };
// Keeps one caption per chosen platform inside that platform's limit.
const ai = $json.output ?? {};
const s = $('Your settings').first().json;
const notes = clean(s.message.caption || s.message.text || '');
const wanted = String(s.platforms).split(',').map((p) => p.trim().toLowerCase()).filter((p) => LIMITS[p]);
const fallback = clip(ai.captions?.instagram || ai.captions?.tiktok || notes || 'New video', 2200);
const captions = {};
for (const p of wanted) captions[p] = clip(ai.captions?.[p] || fallback, LIMITS[p]);
const youtube_title = clip(ai.youtube_title || notes || 'New video', 100);
const md = (t) => String(t ?? '').replace(/([_*`\[])/g, '\\$1');
const preview = wanted.map((p) => NAMES[p] + ':\n' + md(captions[p])).join('\n\n') + (captions.youtube ? '\n\nYouTube title: ' + md(youtube_title) : '');
return [{ json: { hook_idea: md(clean(ai.hook_idea)), captions, youtube_title, preview } }];

