// Reads width, height and duration from the MP4/MOV header. Postdom's upload asks for all three.
const readMp4 = (buf) => {
  const boxes = (start, end) => { const out = []; let p = start; while (p + 8 <= end) { let size = buf.readUInt32BE(p); const type = buf.toString('latin1', p + 4, p + 8); let header = 8; if (size === 1) { size = Number(buf.readBigUInt64BE(p + 8)); header = 16; } else if (size === 0) { size = end - p; } if (size < header || p + size > end) break; out.push({ type, start: p, header, end: p + size }); p += size; } return out; };
  const top = boxes(0, buf.length);
  const moov = top.find((b) => b.type === 'moov');
  if (!moov) return null;
  const inner = boxes(moov.start + moov.header, moov.end);
  const mvhd = inner.find((b) => b.type === 'mvhd');
  if (!mvhd) return null;
  const v = buf[mvhd.start + 8]; const o = mvhd.start + 12;
  const timescale = v === 1 ? buf.readUInt32BE(o + 16) : buf.readUInt32BE(o + 8);
  const duration = v === 1 ? Number(buf.readBigUInt64BE(o + 20)) : buf.readUInt32BE(o + 12);
  let width = 0; let height = 0;
  for (const trak of inner.filter((b) => b.type === 'trak')) {
    const tkhd = boxes(trak.start + trak.header, trak.end).find((b) => b.type === 'tkhd');
    if (!tkhd) continue;
    const w = Math.round(buf.readUInt32BE(tkhd.end - 8) / 65536); const h = Math.round(buf.readUInt32BE(tkhd.end - 4) / 65536);
    if (!w || !h) continue;
    const m = tkhd.end - 44; const a = buf.readInt32BE(m); const b = buf.readInt32BE(m + 4);
    const rotated = a === 0 && b !== 0;
    width = rotated ? h : w; height = rotated ? w : h; break;
  }
  const brand = top[0] && top[0].type === 'ftyp' ? buf.toString('latin1', top[0].start + 8, top[0].start + 12) : '';
  return { width, height, seconds: timescale ? Math.max(1, Math.round(duration / timescale)) : 0, mime: brand === 'qt  ' ? 'video/quicktime' : 'video/mp4' };
};

const meta = $('Your settings').first().json.message.video || {};
const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
  const info = readMp4(buf) || {};
  const binary = items[i].binary;
  binary.data.mimeType = info.mime || 'video/mp4';
  const width = meta.width || info.width; const height = meta.height || info.height; const seconds = meta.duration || info.seconds;
  out.push({ json: { usable: Boolean(width && height && seconds), width_pixels: width, height_pixels: height, duration_seconds: seconds }, binary, pairedItem: i });
}
return out;

