// One Postdom post per platform, so each platform gets its own caption.
const s = $('Your settings').first().json;
const fit = $('Fit captions').first().json;
const upload = $('Upload video to Postdom').first().json;
const wanted = Object.keys(fit.captions);
const accounts = $input.all().map((i) => i.json).filter((a) => a.status === 'connected' && wanted.includes(a.platform));
if (accounts.length === 0) throw new Error('No connected Postdom account for: ' + wanted.join(', ') + '. Connect one at https://app.postdom.com and send the video again.');
const minutes = Number(s.publish_delay_minutes) || 0;
const publish_at = minutes > 0 ? new Date(Date.now() + minutes * 60000).toISOString().replace(/\.\d{3}Z$/, 'Z') : '';
const groups = {};
for (const a of accounts) (groups[a.platform] ||= []).push(a.providerAccountId);
return Object.entries(groups).map(([platform, ids]) => ({ json: {
  platform,
  account_ids: ids.join(','),
  caption: fit.captions[platform],
  youtube_title: fit.youtube_title,
  media_handle: upload.media_handle,
  publish_at,
  idempotency_key: keyFrom('n8n-telegram', upload.media_handle, platform),
} }));

